def test_AC14_1_5_smoke_test_succeeds_against_mocked_local_environment(tmp_path: Path) -> None: 'AC-meta.foundation-tooling.5'; fake_bin = tmp_path / 'bin'; fake_bin.mkdir(); fake_curl = fake_bin / 'curl'; fake_curl.write_text(textwrap.dedent('            #!/usr/bin/env python3\n            import sys\n\n            args = sys.argv[1:]\n            url = next((arg for arg in reversed(args) if arg.startswith("http")), "")\n\n            if "-I" in args:\n                print("HTTP/1.1 204 No Content")\n                print("Access-Control-Allow-Origin: http://example.test")\n                raise SystemExit(0)\n\n            status = "401" if url.endswith("/api/statements") else "200"\n            body = \'{"status":"healthy","state":"pong"}\' if "/api/health" in url or url.endswith("/api/ping") else "OK"\n\n            if "-o" in args and "/dev/null" in args:\n                print(status, end="")\n            elif "-w" in args:\n                print(body)\n                print(status)\n            else:\n                print(body)\n            '), encoding='utf-8'); fake_curl.chmod(fake_curl.stat().st_mode | stat.S_IXUSR); env = {**os.environ, 'PATH': f"{fake_bin}{os.pathsep}{os.environ['PATH']}", 'SMOKE_READY_ATTEMPTS': '1', 'SMOKE_READY_SLEEP_SECONDS': '0'}; result = subprocess.run(['bash', str(REPO_ROOT / 'tools' / 'smoke_test.sh'), 'http://example.test', 'prod'], check=False, env=env, text=True, capture_output=True); assert result.returncode == 0, result.stdout + result.stderr; assert 'All smoke tests passed!' in result.stdout; assert 'Protected endpoint is secured' in result.stdout
